let einkaufsliste = ['Brot', 'Milch'];
einkaufsliste.push('Eier');
console.log(einkaufsliste);

einkaufsliste.pop();
console.log(einkaufsliste);

let punkte = [12, 7, 19, 3];
for (const punkt of punkte) {
  console.log(punkt);
}

let zahlen = [4, 9, 15, 22, 7];
let anzahlGerade = 0;
for (const zahl of zahlen) {
  if (zahl % 2 === 0) {
    anzahlGerade++;
  }
}
console.log(`Gerade Zahlen: ${anzahlGerade}`);

let liste = ['a', 'b'];
let ergebnis = liste.push('c');
console.log(ergebnis);

let noten = [2, 3, 1, 4];
for (let i = 0; i <= noten.length; i++) {
  console.log(noten[i]);
}
